--
-- Name: purge_old_audit_logs(); Type: FUNCTION; Schema: public; Owner: cj_admin
--

CREATE FUNCTION public.purge_old_audit_logs() RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    deleted_count INT;
BEGIN
    DELETE FROM audit_logs
    WHERE created_at < NOW() - INTERVAL '2 years';
    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    RETURN deleted_count;
END;
$$;


ALTER FUNCTION public.purge_old_audit_logs() OWNER TO cj_admin;

